function validateDesign(raw){if(!raw||typeof raw!=='object'||raw.version!==2||!Array.isArray(raw.items)||!raw.room)throw new Error('이 스튜디오에서 저장한 배치 JSON 파일을 선택하세요.');const next=initialState(),r=raw.room;if(!['w','d','h'].every(k=>Number.isFinite(r[k]))||r.w<3||r.w>30||r.d<3||r.d>30||r.h<2||r.h>6)throw new Error('방 치수가 올바르지 않습니다.');next.room={w:r.w,d:r.d,h:r.h,tile:.45};if(raw.items.length>300)throw new Error('가구는 최대 300개까지 불러올 수 있습니다.');const ids=new Set(),counts={};next.items=raw.items.map((i,n)=>{const c=spec(i.type);if(!c||!Number.isFinite(i.x)||!Number.isFinite(i.z)||Math.abs(i.x)>100||Math.abs(i.z)>100||!Number.isFinite(i.rot||0))throw new Error('가구 정보가 올바르지 않습니다.');counts[i.type]=(counts[i.type]||0)+1;const item={id:typeof i.id==='string'&&/^[\w-]{1,100}$/.test(i.id)&&!ids.has(i.id)?i.id:`import-${Date.now()}-${n}`,type:i.type,x:i.x,z:i.z,rot:(i.rot||0)%360,y:Number(i.y)||0,locked:!!i.locked};ids.add(item.id);if(i.type==='screen')item.screenRaised=readScreenRaised(i.screenRaised);if(isDesk(i.type))item.monitors=validateMonitors(i.type,i.monitors);if(i.name)item.name=String(i.name).slice(0,60);if(i.dims){if(!validItemDimensions(i.type,i.dims))throw new Error('가구 치수가 올바르지 않습니다.');item.dims=i.dims;}Object.assign(item,validateCoverAppearance(i,item,next.room));syncFullHeightWall(item,next.room);if(item.y<0||item.y+dimsOf(item,CATALOG)[2]>r.h+.01)throw new Error('가구 높이가 천장 범위를 초과합니다.');return contain(item,next.room,CATALOG);});
 if(Array.isArray(raw.fixtures)){if(raw.fixtures.length>80)throw new Error('고정 시설은 80개 이하로 불러올 수 있습니다.');next.fixtures=raw.fixtures.map((f,n)=>{if(!['door','window','panel','idf','sink','floorbox'].includes(f.kind)||!Number.isFinite(f.w)||!Number.isFinite(f.h)||f.w<.02||f.w>30||f.h<.005||f.h>r.h)throw new Error('고정 시설 정보가 올바르지 않습니다.');const g={id:'fixture-'+n,kind:f.kind,name:String(f.name||'시설').slice(0,50),w:f.w,h:f.h,depth:Number(f.depth)||.08,estimated:f.estimated!==false,hidden:!!f.hidden};if(typeof f.id==='string'&&/^[\w-]+$/.test(f.id))g.id=f.id;if(f.kind==='floorbox'){if(!Number.isFinite(f.x)||!Number.isFinite(f.z)||f.x<0||f.x>r.w||f.z<0||f.z>r.d)throw new Error('바닥 단자 좌표가 올바르지 않습니다.');g.x=f.x;g.z=f.z;}else{if(!['front','back','left','right'].includes(f.wall)||!Number.isFinite(f.offset)||f.offset<0)throw new Error('벽면 시설 좌표가 올바르지 않습니다.');if(g.depth<.01||g.depth>3)throw new Error('시설 깊이가 올바르지 않습니다.');g.wall=f.wall;g.offset=f.offset;g.bottom=Number(f.bottom)||0;const len=['front','back'].includes(f.wall)?r.w:r.d;if(g.offset+g.w>len+.01||g.bottom<0||g.bottom+g.h>r.h+.01)throw new Error('벽면 시설이 방 범위를 벗어납니다.');}return g;});}
 next.fixtures=migrateLegacyFloorBoxes(next.fixtures,next.room);validateFixtures(next.fixtures,next.room);Object.assign(next,readProjectInfo(raw));for(const key of ['smart','grid','labels','fullWalls','computers','limitInventory'])if(raw.settings&&key in raw.settings)next.settings[key]=!!raw.settings[key];if([0,.01,.05,.45].includes(raw.settings?.snap))next.settings.snap=raw.settings.snap;return next;}
async function importFile(file){if(!file)return;if(file.size>3e6)return toast('3MB 이하의 배치 JSON 파일을 선택하세요.');try{const next=validateDesign(JSON.parse(await file.text()));confirmAction('배치 파일을 불러올까요?',`${next.items.length}개 가구가 포함되어 있습니다. 현재 배치는 실행 취소로 복원할 수 있습니다.`,()=>{checkpoint();state=next;selection.clear();changed({room:true});setView(view);resize();toast('배치 파일을 불러왔습니다.');},'불러오기');}catch(e){toast(e instanceof SyntaxError?'JSON 형식이 올바르지 않습니다.':e.message);}}
function exampleLayout(){const apply=()=>{checkpoint();state.items=[];let n=1;const r=state.room,scaleX=r.w/9,scaleZ=r.d/12;for(let row=0;row<6;row++)for(let col=0;col<3;col++){const i=newItem('computerDesk',(1.55+col*2.85)*scaleX,(3.15+row*1.27)*scaleZ);i.name=`컴퓨터책상 ${String(n++).padStart(2,'0')}`;state.items.push(contain(i,r,CATALOG));}for(const [type,x,z,rot] of [['miniRack',.4,2.2,0],['miniFridge',8.65,2.05,270],['desk',3.25,1.35,180],['desk',6.15,1.35,180],['miniDesk',1.35,1.25,180],['cabinet',8.35,10.6,270],['partition140',6.2,1.95,0],['partition140',3.3,1.95,0],['partition80',.7,1.25,90],['partition80',7.15,1.25,90],['screen',4.5,.08,0]]){const i=newItem(type,x*scaleX,z*scaleZ);i.rot=rot;state.items.push(contain(i,r,CATALOG));}selection.clear();changed();toast('3열 × 6행 예시 배치입니다. 가구를 옮겨 통로와 설비 접근 공간을 조정하세요.');};if(state.items.length)confirmAction('추천 배치를 적용할까요?','현재 가구 배치를 3열 × 6행 예시로 바꿉니다. 실행 취소로 돌아갈 수 있습니다.',apply,'추천 배치 적용');else apply();}
function openHelp(){openDialog('몇 번의 드래그로 완성하는 배치','QUICK GUIDE',`<div class="guide-grid"><div class="guide-card"><h3>01 · 가구 배치</h3><p>오른쪽 가구를 공간으로 끌어 놓으세요.<br>클릭하면 비어 있는 곳에 추가됩니다.<br>선택 후 <kbd>R</kbd>을 누르면 90° 회전합니다.</p></div><div class="guide-card"><h3>02 · 워드처럼 맞춤</h3><p>드래그하면 모서리와 중심에 파란 정렬선이 나타납니다. <kbd>Shift</kbd>+클릭 또는 드래그로 여러 개를 선택한 뒤 맞춤·간격 도구를 사용하세요.</p></div><div class="guide-card"><h3>03 · 화면 조작</h3><p>빈 공간을 드래그하면 3D 시점이 회전합니다. 오른쪽 드래그 또는 <kbd>H</kbd>로 화면 이동, 휠로 확대·축소하세요. 2D에서 더 정확하게 배치할 수 있습니다.</p></div><div class="guide-card"><h3>04 · 실제 거리</h3><p>바닥은 <b>45 × 45cm</b>입니다. <kbd>M</kbd>으로 두 점 사이를 측정하세요. 좌표는 가구 중심, X는 왼쪽 벽, Z는 정면 벽을 기준으로 합니다.</p></div><div class="guide-card"><h3>05 · 저장과 내보내기</h3><p>작업은 브라우저에 자동 저장됩니다. JSON 배치 파일로 PC 간 이동이 가능하며, 도면만 또는 설명을 포함해 PNG·PDF로 다운로드할 수 있습니다.</p></div><div class="guide-card"><h3>06 · 사진과 치수</h3><p>가구 크기·수량은 파일명 기준입니다. 공간 설정에서 방 크기를 바꾸고 문·창문·단자함·싱크대를 추가·삭제하거나 치수를 수정할 수 있습니다. 의자·PC 치수와 파티션 두께는 추정값입니다.</p></div></div><p class="modal-note"><b>단축키</b> <kbd>V</kbd>선택 · <kbd>H</kbd>화면 이동 · <kbd>M</kbd>측정 · <kbd>R</kbd>회전 · <kbd>Delete</kbd>삭제 · <kbd>Ctrl+D</kbd>복제 · <kbd>Ctrl+Z</kbd>실행 취소 · <kbd>Ctrl+A</kbd>모두 선택 · <kbd>Esc</kbd>선택 해제</p>`,760);}
function drawPlan(c,{x0,y0,scale,drawingOnly=false}){const w=state.room.w*scale,d=state.room.d*scale;
  c.fillStyle='#e9e6df';c.fillRect(x0,y0,w,d);c.strokeStyle='#d0cec4';c.lineWidth=1;for(let x=0;x<=state.room.w+.001;x+=.45){c.beginPath();c.moveTo(x0+x*scale,y0);c.lineTo(x0+x*scale,y0+d);c.stroke();}for(let z=0;z<=state.room.d+.001;z+=.45){c.beginPath();c.moveTo(x0,y0+z*scale);c.lineTo(x0+w,y0+z*scale);c.stroke();}c.strokeStyle='#82958a';c.lineWidth=7;c.strokeRect(x0,y0,w,d);
  for(const i of state.items.filter(i=>isWallCover(i.type))){const [cw,cd]=dimsOf(i,CATALOG);c.save();c.translate(x0+i.x*scale,y0+i.z*scale);c.rotate(-(i.rot||0)*Math.PI/180);c.fillStyle=coverColor(i);c.strokeStyle=coverColor(i);c.lineWidth=2;c.fillRect(-cw*scale/2,-cd*scale/2,cw*scale,Math.max(1,cd*scale));c.strokeRect(-cw*scale/2,-cd*scale/2,cw*scale,Math.max(1,cd*scale));c.restore();}
  for(const f of state.fixtures.filter(f=>!f.hidden)){const p=fixtureTransform(f);c.save();c.translate(x0+p.x*scale,y0+p.z*scale);c.rotate(-p.angle);if(f.kind==='window'){c.fillStyle='#d0e3e2';c.fillRect(-f.w/2*scale,-9,f.w*scale,18);c.strokeStyle='#4e7475';c.lineWidth=2;c.strokeRect(-f.w/2*scale,-9,f.w*scale,18);}else if(f.kind==='door'){c.fillStyle='#fff';c.fillRect(-f.w/2*scale,-6,f.w*scale,12);c.strokeStyle='#8a9d8a';c.lineWidth=2;c.beginPath();c.moveTo(-f.w/2*scale,0);c.lineTo(-f.w/2*scale,f.w*.75*scale);c.arc(-f.w/2*scale,0,f.w*.75*scale,Math.PI/2,0,true);c.stroke();}else{c.fillStyle=f.kind==='sink'?'#bacbc7':f.kind==='floorbox'?'#a6b4b1':'#a0b3a7';c.fillRect(-f.w*scale/2,f.kind==='floorbox'?-f.depth*scale/2:0,f.w*scale,(f.depth||.08)*scale);}c.restore();}
  for(let n=0;n<state.items.length;n++){const i=state.items[n],[iw,id,ih]=dimsOf(i,CATALOG);if(isWallCover(i.type))continue;c.save();c.translate(x0+i.x*scale,y0+i.z*scale);c.rotate(-(i.rot||0)*Math.PI/180);c.fillStyle=i.type==='fullHeightWall'?'#d4d9d3':i.type.includes('partition')?'#9daeb5':i.type==='chair'?'#606c65':i.type==='computer'?'#61737a':i.type==='screen'?'#f5f2d9':i.type==='miniRack'?'#a4adb0':i.type==='miniFridge'?'#edf0ed':'#d0b084';c.strokeStyle=collisions.has(i.id)?'#c48e55':'#8e9e8f';c.lineWidth=1.6;c.fillRect(-iw*scale/2,-id*scale/2,iw*scale,id*scale);c.strokeRect(-iw*scale/2,-id*scale/2,iw*scale,id*scale);c.fillStyle='#43594a';c.textAlign='center';c.textBaseline='middle';c.font=`600 ${i.type.startsWith('partition')?12:16}px "Malgun Gothic",sans-serif`;if(drawingOnly){const label=itemName(i),maxWidth=Math.max(24,iw*scale-10);c.font=`500 ${Math.min(17,Math.max(11,scale*.085))}px \"Malgun Gothic\",sans-serif`;if((i.rot||0)%360>90&&(i.rot||0)%360<270)c.rotate(Math.PI);if(id<.15){c.textBaseline='bottom';c.fillText(label,0,-id*scale/2-5,maxWidth);}else{let text=label;while(text.length>2&&c.measureText(text).width>maxWidth)text=text.slice(0,-2)+'…';c.fillText(text,0,0,maxWidth);}}else if(id<.15){c.textBaseline='bottom';c.fillText(String(n+1).padStart(2,'0'),0,-id*scale/2-4);}else c.fillText(String(n+1).padStart(2,'0'),0,0);c.restore();}
  if(showClearances){const data=currentClearanceData(),gaps=[...data.deskDepth,...data.deskRows.measurements,...data.distances];c.save();for(const row of data.deskRows.rows){c.font='600 16px sans-serif';c.textAlign='center';c.fillStyle='#7962a6';c.fillText(row.number+'행',x0+data.deskRows.laneX*scale,y0+(row.front+row.back)/2*scale);}for(const m of gaps){const ax=x0+m.a.x*scale,ay=y0+m.a.z*scale,bx=x0+m.b.x*scale,by=y0+m.b.z*scale;c.strokeStyle=m.kind==='desk-depth'?(m.overlap>.005?'#bb6e53':'#397cb1'):m.kind==='row'?'#8a6ab2':m.kind==='wall'?'#7c9aab':'#639578';c.lineWidth=1.2;c.beginPath();c.moveTo(ax,ay);c.lineTo(bx,by);c.stroke();c.textAlign='center';c.textBaseline='bottom';c.font='14px sans-serif';c.lineWidth=4;c.strokeStyle='#fffffff0';c.strokeText(clearanceText(m),(ax+bx)/2,(ay+by)/2-3);c.fillStyle=m.kind==='desk-depth'?(m.overlap>.005?'#aa5f47':'#2c6c9e'):m.kind==='row'?'#795ba4':m.kind==='wall'?'#5d8497':'#3c7954';c.fillText(clearanceText(m),(ax+bx)/2,(ay+by)/2-3);}c.restore();}
  c.textAlign='center';c.fillStyle='#829387';c.font='18px "Malgun Gothic",sans-serif';c.fillText('정면',x0+w/2,y0-35);c.fillText('후면',x0+w/2,y0+d+44);c.fillText(state.room.w.toFixed(2)+' m',x0+w/2,y0+d+82);c.save();c.translate(x0-45,y0+d/2);c.rotate(-Math.PI/2);c.fillText(state.room.d.toFixed(2)+' m',0,0);c.restore();c.textAlign='left';
}
function createSceneExport(){
 const source=renderer.domElement,ratio=source.width/source.height,W=ratio>=1?2200:Math.round(2200*ratio),H=ratio>=1?Math.round(2200/ratio):2200;
 const cv=document.createElement('canvas');cv.width=W;cv.height=H;
 const exportCamera=view==='3d'?camera.clone():new THREE.PerspectiveCamera(38,ratio,.1,250);
 if(view!=='3d'){const r=state.room,target=new THREE.Vector3(r.w/2,0,r.d/2),size=Math.max(r.w,r.d);exportCamera.position.set(target.x+size, size*1.25, target.z+size*1.35);exportCamera.lookAt(target);}
 const pixelRatio=renderer.getPixelRatio?.()||renderer.pixelRatio||1,groups=[selectionGroup,ghostGroup].filter(Boolean),visibility=groups.map(g=>g.visible);
 try{
  groups.forEach(g=>g.visible=false);const direction=exportCamera.position.clone().sub(new THREE.Vector3(state.room.w/2,0,state.room.d/2));
  for(const {mesh,wall} of wallSegments){const near=wall==='front'?direction.z<0:wall==='back'?direction.z>0:wall==='left'?direction.x<0:direction.x>0;const faded=!state.settings.fullWalls&&near;mesh.material.transparent=faded;mesh.material.opacity=faded?.075:1;mesh.material.depthWrite=!faded;mesh.castShadow=!faded;mesh.material.needsUpdate=true;}
  renderer.setPixelRatio(1);renderer.setSize(W,H,false);renderer.render(scene,exportCamera);cv.getContext('2d').drawImage(source,0,0,W,H);
 }finally{groups.forEach((g,n)=>g.visible=visibility[n]);renderer.setPixelRatio(pixelRatio);resize();updateWallVisibility();renderer.render(scene,camera);dirtyRender=true;}
 return cv;
}
function createDrawingExport(mode){
 if(mode==='3d')return createSceneExport();
 const scale=2200/Math.max(state.room.w,state.room.d),cv=document.createElement('canvas');cv.width=Math.ceil(state.room.w*scale+180);cv.height=Math.ceil(state.room.d*scale+170);
 const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,cv.width,cv.height);drawPlan(c,{x0:90,y0:65,scale,drawingOnly:true});return cv;
}
async function createExport(mode='2d',{drawingOnly=true}={}){if(drawingOnly)return createDrawingExport(mode);const W=2400,H=1740,pad=100;const cv=document.createElement('canvas');cv.width=W;cv.height=H;const c=cv.getContext('2d');c.fillStyle='#f7f8f6';c.fillRect(0,0,W,H);c.fillStyle='#294d3d';c.font='600 38px "Malgun Gothic",sans-serif';c.fillText(state.title+' · '+(mode==='2d'?'평면 배치도':'3D 배치도'),pad,95,W-pad*2-300);c.fillStyle='#8e9c92';c.font='18px "Malgun Gothic",sans-serif';const projectCaption=[state.projectLabel,state.planLabel].filter(Boolean).join(' · ');c.fillText(`${projectCaption?projectCaption+'  |  ':''}${state.room.w.toFixed(2)} × ${state.room.d.toFixed(2)}m  |  ${round(state.room.w*state.room.d,1)}㎡  |  바닥 타일 45 × 45cm`,pad,137,W-pad*2);c.textAlign='right';c.fillText(new Date().toLocaleDateString('ko-KR'),W-pad,95);c.textAlign='left';
 if(mode==='2d'){
  const x0=pad+100,y0=215,availW=1570,availH=H-375,scale=Math.min(availW/state.room.w,availH/state.room.d),w=state.room.w*scale,d=state.room.d*scale;
  drawPlan(c,{x0,y0,scale});
 }else{const image=createSceneExport(),rw=image.width,rh=image.height,s=Math.min(1600/rw,(H-380)/rh);c.drawImage(image,pad,190,rw*s,rh*s);}
 const lx=W-630;let ly=230;c.textAlign='left';if(showClearances){const data=currentClearanceData().deskRows;if(data.rows.length){c.fillStyle='#795ba4';c.font='600 21px sans-serif';c.fillText('책상 행 · 테이프 기준 (cm)',lx,ly);ly+=30;c.fillStyle='#849086';c.font='14px sans-serif';c.fillText(data.source+' · 정면 벽 → 행 앞끝 / 다음 행까지',lx,ly);ly+=29;for(const row of data.rows.slice(0,12)){c.fillStyle='#716185';c.font='16px sans-serif';c.fillText(`${row.number}행  ${rowFrontText(row)}  /  ${rowGapText(row)}`,lx,ly);ly+=27;}if(data.rows.length>12){c.fillText('그 외 행은 사이트의 행별 표에서 확인',lx,ly);ly+=27;}ly+=20;}}const exportLimit=Math.max(0,Math.min(35,Math.floor((H-180-ly)/36)));c.textAlign='left';c.textBaseline='alphabetic';c.fillStyle='#365c46';c.font='600 22px "Malgun Gothic",sans-serif';c.fillText('배치 목록',lx,ly);ly+=43;for(let n=0;n<state.items.length&&n<exportLimit;n++){const i=state.items[n];c.fillStyle='#728576';c.font='16px "Malgun Gothic",sans-serif';c.fillText(`${String(n+1).padStart(2,'0')}  ${(itemName(i)+(isWallCover(i.type)?' · '+coverColorName(i):'')).slice(0,28)}`,lx,ly);c.fillStyle='#9da79e';c.font='13px "Malgun Gothic",sans-serif';c.fillText(`${dimsOf(i,CATALOG).map(fmt).join(' × ')}cm · ${i.rot||0}°${isDesk(i.type)?` · PC ${monitorsFor(i).filter(Boolean).length}세트`:''}${i.type==='screen'?(i.screenRaised?' · 올림':' · 내림'):''}`,lx,ly+20);ly+=36;}if(state.items.length>exportLimit){c.font='15px sans-serif';c.fillText(`외 ${state.items.length-exportLimit}개 (전체 목록은 배치 JSON 파일 참고)`,lx,ly+10);}if(!state.items.length){c.fillStyle='#9aa99e';c.font='18px sans-serif';c.fillText('배치된 가구가 없습니다.',lx,ly);}
 c.fillStyle='#a7b0a5';c.font='16px "Malgun Gothic",sans-serif';c.fillText('사진을 참고한 배치 검토용 · 문·창문·설비 치수 및 위치는 추정값 포함 · 시공 전 현장 실측 필요',pad,H-60);if(collisions.size){c.fillStyle='#b28a58';c.fillText(`겹침 또는 출입문 앞 공간 확인: ${collisions.size}개 가구`,pad,H-90);}return cv;
}
async function openExport(){
 openDialog('배치 도면 내보내기','EXPORT YOUR SPACE',`<p style="margin-top:0">미리 보이는 도면을 PNG 이미지나 PDF로 저장하세요.</p><div class="photo-tabs"><button id="exportPlanTab" class="active">2D 평면 배치도</button><button id="export3dTab">3D 공간</button></div><div class="export-options"><label class="checkbox-row"><input type="checkbox" id="drawingOnly" checked>도면만 저장 <small>제목·날짜·가구 목록 제외</small></label><label class="pdf-paper">PDF 용지<select id="pdfPaper" aria-label="PDF 용지"><option value="a4">A4</option><option value="a3">A3</option></select></label></div><img id="exportPreview" class="export-preview" alt="내보낼 배치도 미리보기"><p id="exportDescription" class="modal-note">도면만 담습니다. 2D 치수와 현재 켜 둔 간격 표시도 포함됩니다.</p><div class="dialog-actions export-actions"><button class="button quiet" id="exportJson" data-icon="save">배치 JSON</button><a class="button quiet" id="downloadPng" role="button" data-icon="image" aria-disabled="true" download>PNG 다운로드</a><a class="button primary" id="downloadPdf" role="button" data-icon="download" aria-disabled="true" download>PDF 다운로드</a></div>`,850);
 const preview=$('exportPreview');let mode='2d',job=0,urls=[];
 const release=()=>{urls.forEach(url=>URL.revokeObjectURL(url));urls=[];};
 $('dialog').addEventListener('close',()=>{job++;release();},{once:true});
 const update=async m=>{
  if(m)mode=m;const request=++job;for(const id of ['downloadPng','downloadPdf']){$(id).setAttribute('aria-disabled','true');$(id).removeAttribute('href');}
  $('exportPlanTab').classList.toggle('active',mode==='2d');$('export3dTab').classList.toggle('active',mode==='3d');
  try{
   const only=$('drawingOnly').checked,paper=$('pdfPaper').value,output=await createExport(mode,{drawingOnly:only});
   const [png,jpeg]=await Promise.all([new Promise(resolve=>output.toBlob(resolve,'image/png')),new Promise(resolve=>output.toBlob(resolve,'image/jpeg',.97))]);
   if(!png||!jpeg)throw new Error('이미지 변환 실패');
   const pdf=new Blob([pdfFromJpeg(new Uint8Array(await jpeg.arrayBuffer()),output.width,output.height,paper)],{type:'application/pdf'});
   if(request!==job||$('exportPreview')!==preview||!$('dialog').open)return;
   release();const pngUrl=URL.createObjectURL(png),pdfUrl=URL.createObjectURL(pdf);urls=[pngUrl,pdfUrl];
   $('exportPreview').src=pngUrl;const stem=`${projectFileStem(state)}_${mode==='2d'?'평면':'3D'}배치도${only?'':'_설명포함'}`;
   for(const [id,url,ext] of [['downloadPng',pngUrl,'png'],['downloadPdf',pdfUrl,'pdf']]){$(id).href=url;$(id).download=stem+'.'+ext;$(id).setAttribute('aria-disabled','false');}
   $('exportDescription').textContent=only?'도면만 담습니다. 2D 치수와 현재 켜 둔 간격 표시도 포함됩니다.':'프로젝트 이름·상태·가구 목록을 포함합니다. PDF는 선택한 용지에 비율을 유지해 맞춥니다.';
  }catch(e){toast('도면을 만들 수 없습니다. '+e.message);}
 };
 $('exportPlanTab').onclick=()=>update('2d');$('export3dTab').onclick=()=>update('3d');$('drawingOnly').onchange=()=>update();$('pdfPaper').onchange=()=>update();
 for(const [id,format] of [['downloadPng','PNG'],['downloadPdf','PDF']])$(id).onclick=e=>{if($(id).getAttribute('aria-disabled')==='true')e.preventDefault();else toast(format+' 도면을 저장했습니다.');};
 $('exportJson').onclick=()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),projectFileStem(state)+'_배치.json');
 await update();
}
